// Generate `cordis.patch.local.yml` — the overlay that boots this working tree.
//
// Run after every build (`npm run build` chains it), because what the overlay
// points at is `lib/`, and a stale overlay would silently boot the last build.
//
// Why a GENERATED file rather than a committed one: an entry's `name` is the
// specifier the loader imports, and `!!js` does not reach it — the loader
// interpolates `config` only (docs/postmortem/0002). So the paths have to be
// literal absolute strings, which makes the file machine-specific. It is
// gitignored for the same reason.
//
// Usage:
//   npm run build
//   dsh --profile web --patch <this file> web

import { writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

/** Absolute path of one entry in this package. */
function packagePath(relative) {
  return fileURLToPath(new URL(`../${relative}`, import.meta.url))
}

const OUTPUT = packagePath('cordis.patch.local.yml')

const content = `# GENERATED by scripts/gen-local-patch.mjs — do not edit, re-run \`npm run build\`.
#
# The LOCAL-DEBUG overlay. It boots this working tree instead of the copy
# \`dsh plugin add\` installed under \`$DSH_HOME/profiles/node_modules\`:
#
#   dsh --profile web --patch ${OUTPUT} web
#
# Edit, \`npm run build\`, restart — no reinstall step in the loop.
#
# It works whether or not the bundle is installed. Every row it disables is
# disabled by id; a patch whose id matches nothing warns ("entry not found")
# and is skipped, so an uninstalled profile just skips those three lines.
#
# Why disable-and-insert rather than repoint the installed rows: a patch's
# \`name\` field is an ASSERTION, not an override — \`applyEntryPatches\` pulls it
# out of the overrides and only uses it to refuse a patch whose id has drifted
# onto a different plugin (vendor/include/src/index.ts). A row's specifier is
# fixed at insert time, so pointing at a different file means a different row.

# ── the installed copy, if any ───────────────────────────────────────────────
- id: dba-agent
  disabled: true

- id: dba-skills
  disabled: true

- id: dba-sql-mcp
  disabled: true

- id: dba-agent-presets
  disabled: true

# ── the harness's own prompt sections ────────────────────────────────────────
#
# Same two switches as cordis.patch.yml, restated so this overlay produces the
# same prompt with or without the bundle installed. See that file for why.
- id: system-prompt
  config:
    includeHarnessIdentity: false

- id: web-runtime
  config:
    surfaceContext: false
    openBrowser: !!js ctx.webStartup.openBrowser
    printUrl: true
    trustedHosts: !!js ctx.webStartup.trustedHosts

# ── the shipped roster ───────────────────────────────────────────────────────
#
# Also disabled here, so this overlay produces the same one-mode picker with or
# without the bundle installed. See cordis.patch.yml for why the row is stopped
# rather than narrowed.
- id: agent-presets
  disabled: true

# ── this working tree ────────────────────────────────────────────────────────
- insert:
    - id: dba-agent-local
      name: '${packagePath('lib/index.js')}'

    - id: dba-skills-local
      name: '@deepseek-ai/dsh-skill-filesystem'
      config:
        providerName: dba
        includeDefaultRoots: false
        customSkillDirs:
          - '${packagePath('skills')}'

    - id: dba-sql-mcp-local
      name: '@deepseek-ai/dsh-mcp-client'
      config:
        serverName: dba_sql
        transport: stdio
        command: node
        args:
          - '${packagePath('lib/mcp/server.js')}'
        env:
          MYSQL_PASSWORD: !!js process.env.MYSQL_PASSWORD ?? ''
        # Loud on a broken build: this path is the point of the whole overlay,
        # and a silently absent server would look like "the tool disappeared".
        failOnStartupError: true

    - id: dba-agent-presets-local
      name: '@deepseek-ai/dsh-agent-presets'
      config:
        default: dba
        roots:
          # \`system\` trust even locally: it is read-only in the UI, and this
          # root is the WORKING TREE — a \`user\` root would put a delete button
          # in the preset list pointed at \`presets/dba/\`.
          - path: '${packagePath('presets')}'
            trust: system
        includeUserRoot: false
`

try {
  writeFileSync(OUTPUT, content)
  console.log(`generated ${OUTPUT}`)
} catch (error) {
  // Never fail a build for this: `prepare` runs the build on install, where the
  // package directory can be read-only and a debug overlay is pointless anyway.
  console.warn(`skipped the local debug overlay: ${error instanceof Error ? error.message : String(error)}`)
}
